{
  "name": "Sensirion SHT85温湿度传感器",
  "name_en": "Sensirion SHT85 Temperature and Humidity Sensor",
  "manufacturer": "Sensirion",
  "description": "用于实验环境中温度与相对湿度测量的数字传感器，可基于温湿度估算露点。该器件支持不同重复精度、周期性异步采样、ART加速湿度响应以及内部加热器调试功能，通常通过I2C接口集成到实验系统中。",
  "description_en": "A digital sensor for measuring temperature and relative humidity in laboratory environments, with dew point estimation based on the measured values. It supports multiple repeatability modes, periodic asynchronous acquisition, ART for faster humidity response, and an internal heater for debugging, typically integrated through an I2C interface.",
  "tag_hints": [
    "temperature sensing",
    "humidity sensing",
    "dew point estimation",
    "I2C sensor",
    "periodic acquisition",
    "ART mode",
    "sensor heater"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化传感器通信与测量状态。",
      "description_en": "Initialize sensor communication and measurement state."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "读取当前温度。",
      "description_en": "Read the current temperature."
    },
    {
      "action_name": "auto-get_humidity",
      "description": "读取当前相对湿度。",
      "description_en": "Read the current relative humidity."
    },
    {
      "action_name": "auto-get_temperature_and_humidity",
      "description": "同时读取当前温度和相对湿度。",
      "description_en": "Read the current temperature and relative humidity together."
    },
    {
      "action_name": "auto-get_dew_point",
      "description": "根据当前温度和湿度计算露点。",
      "description_en": "Calculate the dew point from the current temperature and humidity."
    },
    {
      "action_name": "auto-start_asynchronous_read",
      "description": "按设定采样频率启动周期性异步测量，可选启用ART模式。",
      "description_en": "Start periodic asynchronous measurement at the selected sampling rate, with optional ART mode."
    },
    {
      "action_name": "auto-read_asynchronous",
      "description": "读取下一条可用的异步测量结果；若在超时前无数据可返回空结果。",
      "description_en": "Fetch the next available asynchronous measurement; it may return no data if none is available before timeout."
    },
    {
      "action_name": "auto-stop_asynchronous_read",
      "description": "停止周期性异步测量。",
      "description_en": "Stop periodic asynchronous measurement."
    },
    {
      "action_name": "auto-asynchronous",
      "description": "以指定采样频率和可选ART模式运行异步测量流程。",
      "description_en": "Run the asynchronous measurement workflow with the specified sampling rate and optional ART mode."
    },
    {
      "action_name": "auto-enable_heater",
      "description": "开启传感器内部加热器，用于调试或诊断。",
      "description_en": "Enable the sensor's internal heater for debugging or diagnostics."
    },
    {
      "action_name": "auto-disable_heater",
      "description": "关闭传感器内部加热器。",
      "description_en": "Disable the sensor's internal heater."
    },
    {
      "action_name": "auto-is_heater_on",
      "description": "检查内部加热器是否已开启。",
      "description_en": "Check whether the internal heater is enabled."
    },
    {
      "action_name": "auto-reset_sensor",
      "description": "对传感器执行软复位并重新初始化寄存器。",
      "description_en": "Perform a soft reset of the sensor and reinitialize its registers."
    },
    {
      "action_name": "auto-to_dew_point",
      "description": "根据给定温度和相对湿度使用近似公式计算露点。",
      "description_en": "Calculate dew point from the provided temperature and relative humidity using an approximation formula."
    },
    {
      "action_name": "auto-read",
      "description": "读取当前传感器数据。",
      "description_en": "Read the current sensor data."
    },
    {
      "action_name": "auto-read_synchronous",
      "description": "以同步阻塞方式读取当前传感器数据。",
      "description_en": "Perform a synchronous blocking read of the current sensor data."
    }
  ]
}

